// JavaScript WASM Integration
import init, { grayscale } from './pkg/grayscale.js';

async function processImage(file) {
  await init();

  const reader = new FileReader();
  reader.onload = async (e) => {
    const base64 = e.target.result.split(',')[1];
    const processed = grayscale(base64);
    document.getElementById('output').src = processed;
  };
  reader.readAsDataURL(file);
}

document.getElementById('fileInput')
  .addEventListener('change', (e) => processImage(e.target.files[0]));

