use image::{DynamicImage, GenericImageView, ImageFormat, Png};
use image::io::Reader as ImageReader;

// Load image from bytes
fn load_from_memory(buffer: &[u8]) -> Result<DynamicImage, ImageError> {
    ImageReader::new(Cursor::new(buffer))
        .with_guessed_format()?
        .decode()
}

// Grayscale conversion uses luminosity method:
// Gray = 0.21 R + 0.72 G + 0.07 B
impl DynamicImage {
    pub fn grayscale(&self) -> DynamicImage {
        DynamicImage::ImageLuma8(self.to_luma8())
    }
}

